import json
from collections import defaultdict

from taf.sw.dcap.rd.services.cm.cm_v2 import CMv2
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.start_trace_body_v3 import StartTraceBodyV3
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.start_trace_body_v2_trace_profiles import \
    StartTraceBodyV2TraceProfiles
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.check_preconditions_body_v2 import CheckPreconditionsBodyV2
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.check_preconditions_body_v2_trace_profiles import \
    CheckPreconditionsBodyV2TraceProfiles
from taf.sw.dcap.rd.services.custom_traces.custom_base import CustomTraceBase
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.inline_object1 import InlineObject1
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.inline_object2 import InlineObject2
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CMv3(CMv2):

    def __init__(self, con_details):
        super(CMv3, self).__init__(con_details)

    def check_precondition(self, invalidate_bts_info_cache=None, bts=None, timeout=400, **kwargs):
        trace_profiles = self.start_trace_profile_selection(**kwargs)
        gnb_trace_profiles, enb_trace_profiles, bts_trace_profiles, vcu_trace_profiles, vdu_trace_profiles = \
            self.gnb_enb_trace_body_v2(trace_profiles=trace_profiles)
        check_preconditions_body_v2_trace_profiles = CheckPreconditionsBodyV2TraceProfiles(gnb=gnb_trace_profiles,
                                                                                           bts=bts_trace_profiles,
                                                                                           vcu=vcu_trace_profiles,
                                                                                           vdu=vdu_trace_profiles,
                                                                                           enb=enb_trace_profiles)
        check_preconditions_body = CheckPreconditionsBodyV2(invalidate_bts_info_cache=invalidate_bts_info_cache,
                                                            trace_profiles=check_preconditions_body_v2_trace_profiles,
                                                            bts=bts)
        return self.api_client.check_trace_preconditions_v2(check_preconditions_body_v2=check_preconditions_body,
                                                            _request_timeout=timeout)

    def get_rad_parameters(self, bts, domain, direction, event_based_tracer, tracer="radVdu"):
        rad_values = self.get_params_based_on_direction(bts=bts,
                                                        domain=domain,
                                                        direction=direction,
                                                        event_based_tracer=event_based_tracer)
        formatted_dict = {
            'persistency': "Current",
            'params': rad_values,
            'permanent': False
        }
        json_string = json.dumps(formatted_dict)
        rad_parameters = {
            "tracer": tracer,
            "parameters": [
                {
                    "name": "radParameters",
                    "values": [
                        json_string
                    ]
                }
            ]
        }
        return rad_parameters

    @staticmethod
    def generate_common_parameters(direction, max_no_of_snapshots, sub_cells_info):
        return [
            {
                "name": "direction",
                "values": direction
            },
            {
                "name": "maxNumberOfSnapshots",
                "values": max_no_of_snapshots
            },
            {
                "name": "selectedNrSubcells",
                "values": sub_cells_info
            }
        ]

    def get_vdu_trace_parameters(self, direction, max_no_of_snapshots, time_domain_capture, sub_cells_info):
        tracer_parameters = self.generate_common_parameters(direction, max_no_of_snapshots, sub_cells_info)
        tracer_parameters.append({"name": "timeDomainCapture", "values": time_domain_capture})
        return [{
            "tracer": "eventBasedTracerVdu",
            "parameters": tracer_parameters
        }]

    def get_bts_trace_parameters(self, direction, max_no_of_snapshots, bip, sub_cells_info):
        tracer_parameters = self.generate_common_parameters(direction, max_no_of_snapshots, sub_cells_info)
        tracer_parameters.append({"name": "bip", "values": bip})
        return [{
            "tracer": "eventBasedTracer",
            "parameters": tracer_parameters
        }]

    @staticmethod
    def generate_common_event_based_parameters(event_based_tracer):
        direction = event_based_tracer.get('direction', "UL")
        max_no_of_snapshots = event_based_tracer.get('max_no_of_snapshots', "0")
        sub_cells_info = event_based_tracer.get('sub_cells_info')
        domain = event_based_tracer.get('domain')
        keys_to_check = ['phy_event_enable', 'phy_event_enable_ext', 'dl_event_enable']
        is_key_present = any(key in event_based_tracer for key in keys_to_check)
        return direction, max_no_of_snapshots, sub_cells_info, domain, is_key_present

    def custom_vdu_event_based_tracer(self, bts, kwargs):
        vdu_event_based_tracer = kwargs.get('vdu_event_based_tracer')
        direction, max_no_of_snapshots, sub_cells_info, domain, is_key_present = (
            self.generate_common_event_based_parameters(
                event_based_tracer=vdu_event_based_tracer))
        time_domain_capture = vdu_event_based_tracer.get('time_domain_capture', "false")
        rad_parameters = []
        if is_key_present:
            rad_parameters = self.get_rad_parameters(bts=bts, domain=domain, direction=direction,
                                                     event_based_tracer=vdu_event_based_tracer)
        tracer_parameters = self.get_vdu_trace_parameters(direction=direction, max_no_of_snapshots=max_no_of_snapshots,
                                                          time_domain_capture=time_domain_capture,
                                                          sub_cells_info=sub_cells_info)
        if rad_parameters:
            tracer_parameters.append(rad_parameters)
        return tracer_parameters

    def custom_bts_event_based_tracer(self, bts, kwargs):
        bts_event_based_tracer = kwargs.get('bts_event_based_tracer')
        direction, max_no_of_snapshots, sub_cells_info, domain, is_key_present = self.generate_common_event_based_parameters(
            event_based_tracer=bts_event_based_tracer)
        bip = bts_event_based_tracer.get('bip', "false")
        rad_parameters = []
        if is_key_present:
            rad_parameters = self.get_rad_parameters(bts=bts, domain=domain, direction=direction,
                                                     event_based_tracer=bts_event_based_tracer, tracer="rad")
        tracer_parameters = self.get_bts_trace_parameters(direction=direction, max_no_of_snapshots=max_no_of_snapshots,
                                                          bip=bip,
                                                          sub_cells_info=sub_cells_info)
        if rad_parameters:
            tracer_parameters.append(rad_parameters)
        return tracer_parameters

    @staticmethod
    def update_bts_with_event(bts, event):
        if isinstance(bts, dict):
            bts.update(event)
        elif isinstance(bts, list):
            for bts_dict in bts:
                bts_dict.update(event)

    def start_trace_from(self, bts, tag=None, trace_profiles=None, duration=None, resource_group=None,
                         allow_start_failures=True, force=True, **kwargs):
        gnb_trace_profiles, enb_trace_profiles, bts_trace_profiles, vcu_trace_profiles, vdu_trace_profiles = \
            self.gnb_enb_trace_body_v2(trace_profiles=trace_profiles)
        trace_profiles = StartTraceBodyV2TraceProfiles(gnb=gnb_trace_profiles, bts=bts_trace_profiles,
                                                       vcu=vcu_trace_profiles, vdu=vdu_trace_profiles,
                                                       enb=enb_trace_profiles)
        if kwargs.get('post_processors'):
            post_processors = CustomTraceBase.create_emil_decoder_post_processing(kwargs.get('emil_profile_values'))
        else:
            post_processors = None

        vdu_custom_profile = kwargs.get('vdu_custom_profile', '')
        bts_custom_profile = kwargs.get('bts_custom_profile', '')

        if 'eventBasedTracerVdu' in vdu_custom_profile:
            vdu_event_trace_param = self.custom_vdu_event_based_tracer(bts, kwargs)
            event = {"tracerParameters": vdu_event_trace_param}
            self.update_bts_with_event(bts, event)
        if 'BTSeventBasedTracer' in bts_custom_profile:
            bts_event_trace_param = self.custom_bts_event_based_tracer(bts, kwargs)
            event = {"tracerParameters": bts_event_trace_param}
            self.update_bts_with_event(bts, event)
        else:
            bts = bts
        start_trace_body = StartTraceBodyV3(force=force, tag=tag, bts=bts,
                                            trace_profiles=trace_profiles, duration=duration,
                                            resource_group=resource_group,
                                            allow_start_failures=allow_start_failures,
                                            post_processors=post_processors)
        self._start_trace_body = self.api_client.new_trace_v3(start_trace_body_v3=start_trace_body)
        return self.wait_for_start_trace_activation(wait_for_activation=kwargs.get('wait_for_activation'),
                                                    timeout=kwargs.get('timeout'))

    def start_trace(self, bts, tag, duration, timeout, **kwargs):
        kwargs = {k: v for k, v in kwargs.items() if v is not None}
        trace_profiles = self.start_trace_profile_selection(**kwargs)
        return self.start_trace_from(tag=tag, bts=bts,
                                     trace_profiles=trace_profiles, duration=duration, timeout=timeout, **kwargs)

    def get_all_bts_info(self, timeout):
        return self.api_client.get_all_bts_v3(_request_timeout=timeout)

    def get_bts_by_id(self, bts_id, timeout):
        bts_id = self._get_bts_id(bts_id=bts_id)
        return self.api_client.get_bts_by_id_v3(id=bts_id, _request_timeout=timeout)

    def get_trace_info_by_id(self, trace_id, timeout):
        trace_id = self._get_trace_id(trace_id)
        return self.api_client.get_trace_info_by_id_v3(trace_id=trace_id, _request_timeout=timeout)

    def get_features(self, timeout):
        return self.api_client.get_features(_request_timeout=timeout)

    @staticmethod
    def get_hex_values(domain, rad_conversions, direction):
        common_parameter_names = ['freezeForSuspiciousEvents', 'nbOfEventsToTrigAutoBTSSnapshot']
        if direction == "UL":
            parameter_names = ['phyEventEnable', 'phyEventEnableExt']
        else:
            parameter_names = ['dlPhyEventEnable']

        combined_parameter_names = common_parameter_names + parameter_names
        hex_values = {}

        for item in rad_conversions:
            if item.domain in [domain, 'CommonPhy']:
                for param in item.parameters:
                    if param.name in combined_parameter_names:
                        hex_values[param.name] = param.hex
        return hex_values

    @staticmethod
    def calculate_bitmask(bit_positions):
        if isinstance(bit_positions, str):
            bit_positions = list(bit_positions)
        bitmask = 0
        for bit in bit_positions:
            bitmask |= (1 << int(bit))
        return bitmask

    @staticmethod
    def get_bit_number(suspicious_events, result):  # noqa: C901

        def iter_details(events):
            for event in events:
                for param in event.params:
                    for detail in param.param_details:
                        yield detail

        final_output = defaultdict(list)
        for detail in iter_details(suspicious_events):
            parameter = detail.parameter

            if parameter not in result:
                continue

            def is_valid_json(json_string):
                try:
                    json.loads(json_string)
                    return True
                except ValueError:
                    return False

            json_string = detail.details.replace("'", '"').replace("None", "null")
            if is_valid_json(json_string):
                details = json.loads(json_string)
            else:
                logger.error(f"Invalid JSON: {json_string}")
                continue
            if 'bitmaskValues' not in details:
                logger.error(f"'bitmaskValues' not found in: {details}")
                continue
            bitmask_values = details['bitmaskValues']

            for value in bitmask_values:
                if value['meaning'] not in result[parameter]:
                    continue

                final_output[parameter].append(str(value['bitNumber']))

        return dict(final_output)

    def process_nr_suspicious_events(self, bts_info, result, timeout=60):  # noqa: C901
        nr_suspicious_events = self.api_client.get_nr_suspicious_events(inline_object1=InlineObject1(login=bts_info),
                                                                        _request_timeout=timeout)
        return self.get_bit_number(suspicious_events=nr_suspicious_events,
                                   result=result)

    def process_lte_suspicious_events(self, bts_info, result, timeout=60):  # noqa: C901
        lte_suspicious_events = self.api_client.get_lte_suspicious_events_details(
            inline_object2=InlineObject2(login=bts_info),
            _request_timeout=timeout)
        return self.get_bit_number(suspicious_events=lte_suspicious_events,
                                   result=result)

    def get_params_based_on_direction(self, bts, domain, direction, event_based_tracer):
        """
        This function generates a list of parameters based on a given direction.
        It maps user-friendly keys to actual keys in a dictionary, filters specific keys, and retrieves
        rad conversions. Depending on the domain, it processes suspicious events and calculates bitmasks.
        It then updates the original dictionary with these bitmasks. The function retrieves hex values based on
        the domain, rad conversions, and direction, and creates a list of parameters in the format 'hex_value=value'.
        This list is returned as the final output.
        """
        key_mapping = {
            "suspicious_events": "freezeForSuspiciousEvents",
            "bts_snapshot": "nbOfEventsToTrigAutoBTSSnapshot",
            "dl_event_enable": "dlPhyEventEnable",
            "phy_event_enable": "phyEventEnable",
            "phy_event_enable_ext": "phyEventEnableExt",
        }
        hex_value_keys = {key_mapping.get(user_key, user_key): event_based_tracer[user_key] for user_key in
                          event_based_tracer}

        bitmask_keys = ['phyEventEnable', 'phyEventEnableExt', 'dlPhyEventEnable']
        filtered_hex_values = {key: hex_value_keys[key] for key in bitmask_keys if key in hex_value_keys}

        rad_conversions = self.api_client.get_rad_conversions()
        bit_number = self.process_nr_suspicious_events(bts_info=bts,
                                                       result=filtered_hex_values) \
            if domain == 'NrUlPhy' or 'NrDlPhy' else self.process_lte_suspicious_events(
            bts_info=bts, result=filtered_hex_values)

        bitmasks = {key: self.calculate_bitmask(bit_number[key]) for key in bitmask_keys if key in bit_number}

        hex_value_keys.update({key: bitmasks[key] for key in bitmasks})

        hex_values = self.get_hex_values(domain, rad_conversions, direction)

        param_list = ['{}={}'.format(hex_values[key], hex_value_keys[key]) for key in hex_value_keys if
                      key in hex_values]

        return param_list
